pug:
table.row.hero(role='presentation')
    tr
        td.hero-cell(align='center')
            //- optional hero image
            if true
                a(href='{{ image_link }}' target='_blank')
                    img.hero-img(src='{{ image_url }}' alt='{{ image_alt }}' width='480')
            h1.hero-title {{ title }}
            p.hero-body {{ body }}
            //- CTA button
            table.cta(role='presentation' align='center')
                tr
                    td.butt
                        a.butt-link(href='{{ cta_href }}' target='_blank') {{ cta_label }}

styl:
.row.hero td.hero-cell { padding: 0 24px 32px; text-align: center; }
.row.hero img.hero-img { display: block; margin: 0 auto 24px; max-width: 100%; height: auto; border-radius: {{ image_radius }}px; }
.row.hero h1.hero-title { font-family: 'Helvetica', 'Arial', sans-serif; font-weight: 700; font-size: 32px; line-height: 1.2; color: {{ title_color }}; margin: 0 0 16px; padding: 0; }
.row.hero p.hero-body { font-family: 'Helvetica', 'Arial', sans-serif; font-weight: 400; font-size: 16px; line-height: 1.5; color: {{ body_color }}; margin: 0 0 24px; padding: 0; }
.row.hero table.cta { margin: 0 auto; }
.row.hero td.butt { background-color: {{ button_bg }}; border-radius: {{ button_radius }}px; padding: 0; }
.row.hero a.butt-link { display: block; padding: 14px 32px; font-family: 'Helvetica', 'Arial', sans-serif; font-weight: 700; font-size: 16px; color: {{ button_text_color }}; text-decoration: none; }
